      "path": "src/index.ts",
      "content": "/**\n * dsh-jev-interceptor — System-1 decisions for DeepSeek Harness.\n *\n * One out-of-tree Cordis bundle that classifies pending tool calls with Jev\n * (TypeSafe AI's non-generative \"System One\" model) in milliseconds and uses\n * the answers to (a) escalate risky calls to a human before they run and\n * (b) auto-approve clearly-granted, reversible ones so humans stop clicking\n * through routine approvals.\n *\n * Posture: fail-closed. With no key, during provider cooldown, on timeout, or\n * on any internal error, every hook delegates through `next()` and behavior is\n * stock dsh. The plugin never widens a permission the base composition would\n * not grant (the `never` approval policy is enforced upstream of every\n * listener), never returns `allow` itself (downstream vetoes survive), and is\n * disabled until `enabled: true`.\n *\n * Install: `dsh plugin --profile <name> add dsh-jev-interceptor`, then set\n * `enabled: true` (and eventually `mode: enforce`) in cordis.yml.\n * @module dsh-jev-interceptor\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-agent'\nimport { credentialRef } from '@deepseek-ai/dsh-credentials'\n// Type-only: registers the 'settings' Context key used by installSection.\nimport type {} from '@deepseek-ai/dsh-settings'\nimport { launchEnvironmentOf } from '@deepseek-ai/dsh-launch-environment'\n// Type-only: registers the 'permissionPresets' Context key so `ctx.get` below\n// typechecks; the service itself is consumed structurally and the package is\n// not a runtime dependency.\nimport type {} from '@deepseek-ai/dsh-permission-presets'\nimport type { CommandDefinitionId as CommandDefinitionIdBrand } from '@deepseek-ai/dsh-commands/brand'\nimport type { CommandResult } from '@deepseek-ai/dsh-commands'\n\n/**\n * Command definition brand, mirrored locally instead of imported: the brand\n * function is named `CommandDefinitionId` only in newer dsh API generations\n * (older runtimes export it under different names or not at all), and a plain\n * branded string passes structural validation wherever the field is known.\n */\nconst jevStatsDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-stats' as CommandDefinitionIdBrand\nconst jevOnDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-on' as CommandDefinitionIdBrand\nconst jevOffDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-off' as CommandDefinitionIdBrand\nconst jevModeDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-mode' as CommandDefinitionIdBrand\nconst jevStatusDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-status' as CommandDefinitionIdBrand\nconst jevKeyDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-key' as CommandDefinitionIdBrand\nconst jevCalibrateDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-calibrate' as CommandDefinitionIdBrand\nconst jevLogDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-log' as CommandDefinitionIdBrand\nconst jevImpactDefinitionId: CommandDefinitionIdBrand = 'dsh-jev-interceptor:jev-impact' as CommandDefinitionIdBrand\nimport type {} from '@deepseek-ai/dsh-user-approval/types'\nimport {\n  Config,\n  SETTINGS_NS,\n  liveOf,\n  resolveEndpoint,\n  resolveSettings,\n  type LiveSettings,\n  type ResolvedSettings,\n} from './config.js'\nimport { JevClient } from './jev.js'\nimport { Telemetry } from './telemetry.js'\nimport { createGuardListener, PendingAsks } from './guard.js'\nimport { createPreapproveListener } from './preapprove.js'\nimport { ApprovalTrace, createApprovalLoopListener } from './approval-loop.js'\nimport { createImageOffloadListener } from './image-offload.js'\nimport { createStagnationListener, StagnationTracker, type StagnationThresholds } from './stagnation.js'\nimport { registerJevApi } from './jev-api.js'\nimport { approvalBucketsOf, calibrate, renderCalibration, type CalibrationReport, type ThresholdsInput } from './calibrate.js'\nimport {\n  CalibrationHistory,\n  compareWithPrevious,\n  renderComparisonLines,\n  shouldAppend,\n  snapshotOf,\n} from './calibration-history.js'\nimport { renderImpact, summarizeImpact, type ImpactSummary } from './impact.js'\nimport { parseLogArgs, renderLogTable, toLogCsv, toLogJson } from './telemetry.js'\nimport { join } from 'node:path'\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = 'dsh-jev-interceptor'\n\n/**\n * Services this plugin consumes are all optional at load time: the events it\n * listens to exist in every composition that runs tools, and the seams\n * (credentials, permissionPresets, commands) are resolved defensively. An\n * empty `inject` keeps the plugin loadable in every profile.\n */\nexport const inject: readonly string[] = []\n\nexport { Config } from './config.js'\nexport type { Config as ConfigType } from './config.js'\nexport { resolveSettings, resolveEndpoint, DEFAULTS } from './config.js'\nexport { JevClient } from './jev.js'\nexport type { ClassifyResult, ClassifyCall, DegradeReason } from './jev.js'\nexport { Telemetry } from './telemetry.js'\nexport type { TelemetryEntry, DecisionTag, DecisionAction } from './telemetry.js'\nexport { noul, choice, score } from './types.js'\nexport type { NoulQuestion, ChoiceQuestion, ScoreQuestion, JevQuestion, JevAnswers } from './types.js'\nexport { decideGuard, decidePreapprove, decideStagnation } from './matrix.js'\nexport type { GuardAction, GuardThresholds, PreapproveVerdict, PreapproveThresholds, StagnationAnswers } from './matrix.js'\nexport { CooldownGate, Semaphore, LruCache } from './resilience.js'\nexport { createStagnationListener, StagnationTracker, shouldProbe, summarizeFailure } from './stagnation.js'\nexport type { AttemptRecord, StagnationThresholds, StagnationDeps } from './stagnation.js'\nexport { calibrate, renderCalibration, approvalBucketsOf } from './calibrate.js'\nexport { summarizeImpact, renderImpact } from './impact.js'\nexport type { ImpactSummary } from './impact.js'\nexport { CalibrationHistory, compareWithPrevious, shouldAppend, snapshotOf, renderComparisonLines } from './calibration-history.js'\nexport type { CalibrationSnapshot, CalibrationComparison } from './calibration-history.js'\n\n/** 从已解析设置提取阈值子集（校准基线，与挂点同源）。 */\nfunction thresholdsOf(s: ResolvedSettings): ThresholdsInput {\n  return {\n    guardConfidenceMin: s.guardConfidenceMin,\n    guardDenyConfidence: s.guardDenyConfidence,\n    guardIrreversibleCeiling: s.guardIrreversibleCeiling,\n    guardIrreversibleDenyFloor: s.guardIrreversibleDenyFloor,\n    guardInjectionAskThreshold: s.guardInjectionAskThreshold,\n    preapproveAutoApproveMin: s.preapproveAutoApproveMin,\n    preapproveIrreversibleMax: s.preapproveIrreversibleMax,\n    preapproveInjectionSuspectMax: s.preapproveInjectionSuspectMax,\n  }\n}\n\n/**\n * Mount the guard and pre-approval hooks, the shared Jev client, telemetry,\n * and the `/jev-stats` command.\n * @param ctx - plugin context.\n * @param config - YAML-validated plugin configuration.\n */\nexport function apply(ctx: Context, config: Config): void {\n  const { endpoint, model } = resolveEndpoint(config)\n  const settings = resolveSettings(config)\n  const telemetry = new Telemetry(settings.telemetryDir)\n  const pendingAsks = new PendingAsks()\n  const approvalTrace = new ApprovalTrace()\n\n  /**\n   * 生成一份校准报告并落一份快照：读上一份快照对比「上次建议 → 是否采纳\n   * → 桶变化」，再把本次快照追加进历史（5 分钟去抖）。命令与面板共用；\n   * 定义在 apply 内以闭包 telemetry 与 settings（与挂点同一实例）。\n   */\n  const buildCalibration = async (full: boolean): Promise<{ report: CalibrationReport; extras: string[] }> => {\n    const entries = await telemetry.entries(full ? undefined : 2000)\n    const thresholds = thresholdsOf(settings)\n    const report = calibrate(entries, thresholds)\n    const buckets = approvalBucketsOf(entries)\n    const history = new CalibrationHistory(settings.telemetryDir)\n    const recentSnapshots = await history.recent(1)\n    const previous = recentSnapshots.at(-1)\n    // 传本次窗口大小：与上次口径不同（--all vs 尾窗）时桶变化不可比。\n    const comparison = compareWithPrevious(thresholds, previous, buckets, report.windowSize)\n    const snapshot = snapshotOf(report, thresholds, new Date().toISOString(), buckets)\n    if (shouldAppend(previous, snapshot)) history.append(snapshot)\n    return {\n      report: comparison.previousTs === undefined\n        ? report\n        : {\n          ...report,\n          history: {\n            previousTs: comparison.previousTs,\n            adopted: comparison.adopted.length,\n            ignored: comparison.ignored.length,\n            manual: comparison.manual.length,\n          },\n        },\n      extras: renderComparisonLines(comparison),\n    }\n  }\n\n  // Live settings: the plugin Config is registered with the settings provider\n  // so the Settings → Plugins page renders a form (provider, model, apiKey,\n  // mode, etc.) and /jev-key persists through the user layer. On generations\n  // without the service, the row config stays the whole truth.\n  let liveOverride: LiveSettings | undefined\n  let configOverride: Config | undefined\n  const live = (): LiveSettings => liveOverride ?? liveOf(configOverride ?? config)\n\n  // Register our Config schema with the settings provider → the Plugins page\n  // discovers it via describe() and renders the form.\n  ctx.inject(['settings'], (settingsCtx) => {\n    ctx.logger.info('dsh-jev-interceptor: settings service available, attempting registration')\n    try {\n      const service = settingsCtx.settings as unknown as {\n        installSection: (owner: Context, ns: string, schema: unknown, entry: unknown, hooks: {\n          setSource?: (source: unknown) => void\n        }) => void\n      }\n      service.installSection(ctx, 'jev-interceptor', Config, config, {\n        setSource: (source) => {\n          if (typeof source === 'object' && source !== null) {\n            configOverride = source as Config\n          }\n        },\n      })\n      ctx.logger.info('dsh-jev-interceptor: Settings form registered — configure in Settings → Plugins')\n    } catch (error: unknown) {\n      ctx.logger.warn(`dsh-jev-interceptor: Settings registration failed (${error instanceof Error ? error.message : String(error)})`)\n    }\n  })\n\n  const ref = credentialRef(settings.apiKeyEnv)\n  const resolveKey = async (): Promise<string | undefined> => {\n    // Direct config value (set via /jev-key or Settings form) takes precedence.\n    const apiKey = (configOverride ?? config).apiKey\n    if (apiKey !== undefined && apiKey.length > 0) return apiKey\n    const credentials = ctx.get('credentials')\n    if (credentials !== undefined) {\n      // The seam owns the whole credential plane when present: a miss does not\n      // fall through to ambient values (mirrors the llm-deepseek precedent).\n      const hit = await credentials.resolve(ref)\n      if (hit !== undefined && hit.value.length > 0) return hit.value\n      return undefined\n    }\n    // Without the credentials seam the launching environment is the whole credential plane.\n    const ambient = launchEnvironmentOf(ctx).get(ref)\n    if (ambient !== undefined && ambient.value.length > 0) return ambient.value\n    return undefined\n  }\n\n  const jev = new JevClient({\n    endpoint,\n    model,\n    timeoutMs: settings.timeoutMs,\n    cooldownMs: settings.cooldownMs,\n    failureThreshold: settings.failureThreshold,\n    maxConcurrency: settings.maxConcurrency,\n    cacheSize: settings.cacheSize,\n    resolveKey,\n    telemetry,\n    logger: ctx.logger,\n  })\n\n  // Panel API: browser-side settings page fetches from these routes.\n  // Wrapped in inject to defer registration until the connection service is available.\n  ctx.inject(['connection'], () => {\n  registerJevApi(ctx, {\n    getStatus: () => {\n      const s = live()\n      const cfg = configOverride ?? config\n      return {\n        enabled: s.enabled,\n        mode: s.mode,\n        provider: cfg.provider ?? 'typesafe',\n        model: cfg.model ?? 'jev-latest',\n        keyConfigured: cfg.apiKey !== undefined && cfg.apiKey.length > 0,\n        keySource: cfg.apiKey !== undefined && cfg.apiKey.length > 0 ? 'config' : 'env',\n        guardEnabled: settings.guardEnabled,\n        preapproveEnabled: settings.preapproveEnabled,\n        stagnationEnabled: settings.stagnationEnabled,\n      }\n    },\n    getStats: () => telemetry.statsData(200),\n    // 校准基线用与四个挂点同一份 settings 快照：报告的「当前值」= 实际执行值。\n    // 每次生成都会与上一份快照对比（采纳/忽略/桶变化）并落一份新快照。\n    getCalibration: async (): Promise<CalibrationReport> => (await buildCalibration(false)).report,\n    // 面板每 20s 自动刷新会打这个端点：尾部窗口而非全量（/jev-impact 命令才是全量）。\n    getImpact: async (): Promise<ImpactSummary> => summarizeImpact(await telemetry.entries(5000)),\n    testConnection: (apiKeyOverride) => jev.ping(apiKeyOverride === undefined ? {} : { apiKeyOverride }),\n    getLog: (limit) => telemetry.recentEntries(limit),\n    updateConfig: async (patch) => {\n      // 先立即更新内存（getStatus 立刻能看到，无论 settings 服务是否存在）\n      if (typeof patch['enabled'] === 'boolean') liveOverride = { ...live(), enabled: patch['enabled'] }\n      if (patch['mode'] === 'shadow' || patch['mode'] === 'enforce') liveOverride = { ...live(), mode: patch['mode'] }\n      if (typeof patch['provider'] === 'string') configOverride = { ...(configOverride ?? config), provider: patch['provider'] as Config['provider'] }\n      if (typeof patch['endpoint'] === 'string') configOverride = { ...(configOverride ?? config), endpoint: patch['endpoint'] }\n      if (typeof patch['apiKey'] === 'string') configOverride = { ...(configOverride ?? config), apiKey: patch['apiKey'] }\n      // 再尽力持久化（失败不影响本次运行）\n      try {\n        const settingsService = ctx.get('settings')\n        if (settingsService !== undefined && typeof settingsService.update === 'function') {\n          await settingsService.update(SETTINGS_NS, patch)\n        }\n      } catch { /* 内存已更新，持久化失败仅影响重启后 */ }\n    },\n  })\n  })\n\n  // Optional seams resolved defensively: the plugin loads in every profile.\n\n  if (settings.guardEnabled) {\n    ctx.on('tools/pre-execute', createGuardListener({\n      readOnlyTools: settings.readOnlyTools,\n      excludeTools: settings.excludeTools,\n      thresholds: {\n        confidenceMin: settings.guardConfidenceMin,\n        denyConfidence: settings.guardDenyConfidence,\n        irreversibleCeiling: settings.guardIrreversibleCeiling,\n        irreversibleDenyFloor: settings.guardIrreversibleDenyFloor,\n        injectionAskThreshold: settings.guardInjectionAskThreshold,\n      },\n      recentMessages: settings.recentMessages,\n      recentMessageChars: settings.recentMessageChars,\n      argsHeadChars: settings.argsHeadChars,\n      argsTailChars: settings.argsTailChars,\n      jev,\n      telemetry,\n      pendingAsks,\n      live,\n      // Resolved per event: a capture here could miss a service that activates later.\n      permissionPresets: () => ctx.get('permissionPresets'),\n    }))\n  }\n\n  if (settings.preapproveEnabled) {\n    ctx.on('approval/request', createPreapproveListener({\n      allowlist: settings.preapproveToolAllowlist,\n      thresholds: {\n        autoApproveMin: settings.preapproveAutoApproveMin,\n        irreversibleMax: settings.preapproveIrreversibleMax,\n        injectionSuspectMax: settings.preapproveInjectionSuspectMax,\n      },\n      recentMessages: settings.preapproveRecentMessages,\n      recentMessageChars: settings.recentMessageChars,\n      jev,\n      telemetry,\n      pendingAsks,\n      live,\n      trace: approvalTrace,\n    }), { prepend: true })\n  }\n\n  // Image-offload pre-planning: fills the gap dsh's README admits —\n  // \"nothing plans an offload before dispatch\". Opt-in (default off) because\n  // image/offload events are irreversible on disk; only high-confidence\n  // sacrificial images are offloaded before the request dispatches.\n  if (config.imageOffloadEnabled === true) {\n    ctx.on('agent/pre-step', createImageOffloadListener({\n      live,\n      pressureThreshold: config.imageOffloadPressureThreshold ?? 0.75,\n      minCandidates: config.imageOffloadMinCandidates ?? 3,\n      sacrificeScoreMax: config.imageOffloadSacrificeScoreMax ?? 0.33,\n      sacrificeProbMin: config.imageOffloadSacrificeProbMin ?? 0.8,\n      jev,\n      telemetry,\n    }))\n  }\n\n  // Stagnation detection (opt-in): 换参数死循环检测。observe-and-enrich 形态\n  // （照 repeat-tool-reminder）：不拦截不否决，高置信无进展时注入一条提醒。\n  if (settings.stagnationEnabled) {\n    const stagnationThresholds: StagnationThresholds = {\n      triggerCount: settings.stagnationTriggerCount,\n      failureRatioMin: settings.stagnationFailureRatioMin,\n      cooldownMs: settings.stagnationCooldownMs,\n    }\n    const stagnation = createStagnationListener({\n      live,\n      tracker: new StagnationTracker(settings.stagnationWindow),\n      thresholds: stagnationThresholds,\n      confidenceMin: settings.stagnationConfidenceMin,\n      argsPreviewChars: settings.stagnationArgsPreviewChars,\n      jev,\n      telemetry,\n    })\n    ctx.on('tools/post-execute', stagnation.onPostExecute)\n    ctx.on('agent/pre-step', stagnation.onPreStep)\n  }\n\n  // Approval data loop: durable asked/decided audit events correlate with\n  // pre-approval verdicts, so shadow mode accumulates the agreement dataset\n  // (headline: asks Jev would auto-approve but the human rejected).\n  ctx.on('session/event', createApprovalLoopListener({ trace: approvalTrace, telemetry, live }))\n\n  const setLive = async (patch: Partial<LiveSettings>): Promise<CommandResult> => {\n    // Apply immediately in-process so behavior flips on the next event even\n    // when persistence (or the reload it triggers) is unavailable.\n    liveOverride = { ...live(), ...patch }\n    const settingsService = ctx.get('settings')\n    if (settingsService !== undefined && typeof settingsService.update === 'function') {\n      try {\n        await settingsService.update(SETTINGS_NS, patch)\n        const now = live()\n        return {\n          kind: 'success',\n          text: `dsh-jev-interceptor：已${now.enabled ? '启用' : '停用'}，模式 ${now.mode}。`\n            + ' 已持久化到 profile，下一个工具调用即生效（无需重启）。',\n        }\n      } catch (error: unknown) {\n        ctx.logger.warn(`dsh-jev-interceptor: settings update failed (${error instanceof Error ? error.message : String(error)}); applied in-memory only for this run`)\n      }\n    }\n    const now = live()\n    return {\n      kind: 'success',\n      text: `dsh-jev-interceptor：已${now.enabled ? '启用' : '停用'}，模式 ${now.mode} —— 仅本次运行生效。`\n        + ' 当前 profile 无法持久化插件设置；要永久生效请在 cordis.patch.yml 的 jev-interceptor 行设置 enabled/mode。',\n    }\n  }\n\n  ctx.inject(['commands'], (commandsCtx) => {\n    void commandsCtx.commands.register({\n      definitionId: jevStatsDefinitionId,\n      name: 'jev-stats',\n      description: '查看 Jev 决策统计（默认最近 200 条，--all 全量）',\n      // Without an `input` hint a capable client refuses any non-bare line\n      // (`matchEnter` → `!bare` → not a command) and submits `/jev-stats --all`\n      // as an ordinary prompt, so the handler never receives the flag.\n      input: { hint: '[--all]' },\n      handler: async (invocation): Promise<CommandResult> => {\n        const full = invocation.rawInput.includes('--all')\n        return { kind: 'success', text: await telemetry.stats(full ? undefined : 200) }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevCalibrateDefinitionId,\n      name: 'jev-calibrate',\n      description: '分析影子遥测，输出阈值调整建议（默认最近 2000 条，--all 全量）',\n      input: { hint: '[--all]' },\n      handler: async (invocation): Promise<CommandResult> => {\n        const full = invocation.rawInput.includes('--all')\n        const { report, extras } = await buildCalibration(full)\n        return { kind: 'success', text: renderCalibration(report, extras) }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevImpactDefinitionId,\n      name: 'jev-impact',\n      description: '效果归因：省掉的审批点击、拦截、误批、成本与延迟（全量当前日志）',\n      handler: async (): Promise<CommandResult> => {\n        const entries = await telemetry.entries(undefined)\n        return { kind: 'success', text: renderImpact(summarizeImpact(entries)) }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevLogDefinitionId,\n      name: 'jev-log',\n      description: '查看最近 n 条决策明细（默认 20；--json/--csv 导出原始数据）',\n      input: { hint: '[n] [--json|--csv]' },\n      handler: async (invocation): Promise<CommandResult> => {\n        const args = parseLogArgs(invocation.rawInput)\n        const entries = await telemetry.recentEntries(args.n)\n        if (entries.length === 0) {\n          return { kind: 'success', text: '```\\n⚡ dsh-jev-interceptor\\n\\n  暂无决策记录\\n\\n  运行 /jev-on 启用插件后再查看\\n```' }\n        }\n        if (args.format === 'json') {\n          return { kind: 'success', text: '```json\\n' + toLogJson(entries) + '\\n```' }\n        }\n        if (args.format === 'csv') {\n          return { kind: 'success', text: '```\\n' + toLogCsv(entries) + '\\n```' }\n        }\n        return { kind: 'success', text: renderLogTable(entries, join(settings.telemetryDir, 'telemetry.jsonl')) }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevStatusDefinitionId,\n      name: 'jev-status',\n      description: '查看 Jev 插件当前状态',\n      handler: async (): Promise<CommandResult> => {\n        const s = live()\n        const text = [\n          '```',\n          '⚡ dsh-jev-interceptor 状态',\n          `  运行   ${s.enabled ? '✅ 已启用' : '⏸️ 已停用'}`,\n          `  模式   ${s.mode}${s.mode === 'shadow' ? '（只记录）' : '（执行决策）'}`,\n          `  源     ${config.provider ?? 'typesafe'}`,\n          `  模型   ${model}`,\n          `  守门   ${settings.guardEnabled ? '✅' : '❌'}  预批 ${settings.preapproveEnabled ? '✅' : '❌'}  停滞 ${settings.stagnationEnabled ? '✅' : '❌'}`,\n          `  Key    ${config.apiKey !== undefined && config.apiKey.length > 0 ? '✅ 已配置' : (await resolveKey()) !== undefined ? '✅ 环境变量' : '❌ 未配置（运行 /jev-key <key>）'}`,\n          settings.preapproveToolAllowlist.size === 0 ? '  预批白名单为空，不会自动批任何工具' : '',\n          '  控制: /jev-on /jev-off /jev-mode',\n          '  统计: /jev-stats │ 明细: /jev-log │ 校准: /jev-calibrate │ 归因: /jev-impact',\n          '```',\n        ].filter(line => line.length > 0).join('\\n')\n        return { kind: 'success', text }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevKeyDefinitionId,\n      name: 'jev-key',\n      description: '设置 Jev API key（持久化，不需要环境变量）',\n      input: { hint: '<api-key>' },\n      handler: async (invocation): Promise<CommandResult> => {\n        const key = invocation.rawInput.trim()\n        if (key.length < 10) {\n          return { kind: 'error', text: '用法：/jev-key <你的API密钥>（长度需大于 10 个字符）' }\n        }\n        const settingsService = ctx.get('settings')\n        if (settingsService !== undefined && typeof settingsService.update === 'function') {\n          try {\n            await settingsService.update(SETTINGS_NS, { apiKey: key })\n            return {\n              kind: 'success',\n              text: 'dsh-jev-interceptor：API key 已存储 ✅ 持久化到 profile，无需环境变量，重启后仍生效。下一步：/jev-on 启用插件',\n            }\n          } catch (error: unknown) {\n            ctx.logger.warn(`dsh-jev-interceptor: key storage failed (${error instanceof Error ? error.message : String(error)})`)\n          }\n        }\n        return {\n          kind: 'error',\n          text: '当前 profile 无法持久化设置。备选方案：在 cordis.patch.yml 的 jev-interceptor 行加 apiKey: <你的key>',\n        }\n      },\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevOnDefinitionId,\n      name: 'jev-on',\n      description: '启用 Jev 插件（持久化，无需重启）',\n      handler: async (): Promise<CommandResult> => setLive({ enabled: true }),\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevOffDefinitionId,\n      name: 'jev-off',\n      description: '停用 Jev 插件（持久化，无需重启）',\n      handler: async (): Promise<CommandResult> => setLive({ enabled: false }),\n    })\n    void commandsCtx.commands.register({\n      definitionId: jevModeDefinitionId,\n      name: 'jev-mode',\n      description: '设置模式：shadow（只记录）或 enforce（执行）',\n      // Same reason as jev-stats: only a declared input hint makes the client\n      // admit `/jev-mode enforce` as a command instead of a chat message.\n      input: { hint: 'shadow | enforce' },\n      handler: async (invocation): Promise<CommandResult> => {\n        const arg = invocation.rawInput.trim()\n        if (arg !== 'shadow' && arg !== 'enforce') {\n          return { kind: 'error', text: '用法：/jev-mode <shadow|enforce>\\n  shadow  = 只记录决策，不执行\\n  enforce = 执行决策（deny/ask/自动批）' }\n        }\n        return setLive({ mode: arg })\n      },\n    })\n  })\n\n  const state = live()\n  const allowlistNote = settings.preapproveToolAllowlist.size === 0\n    ? '；预批白名单为空——在 preapproveToolAllowlist 里点名工具前不会自动批任何调用'\n    : ''\n  ctx.logger.info(\n    `dsh-jev-interceptor：${state.enabled ? `运行中（${state.mode} 模式）` : '已注册但停用'}`\n    + `（provider ${endpoint}，模型 ${model}）；/jev-on 和 /jev-mode 可运行时切换${allowlistNote}`,\n  )\n}\n"
    },
    {
      "path": "src/config.ts",
      "content": "/**\n * Plugin configuration. Every deployment-varying choice is a schema field so\n * `cordis.yml` can change it without a code edit; defaults keep the plugin\n * inert (`enabled: false`) and conservative (`mode: 'shadow'`).\n * @module dsh-jev-interceptor/config\n */\n\nimport z from '@deepseek-ai/schemastery'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\n\n/**\n * Complete plugin configuration, validated by the same-named schema.\n *\n * All fields are optional in YAML. `enabled: false` (the default) makes the\n * plugin register nothing and behave exactly like an absent plugin; turning it\n * on starts in `shadow` mode, which observes and records decisions without\n * enforcing them.\n */\nexport interface Config {\n  /** Master switch; `false` (default) leaves stock behavior untouched. */\n  enabled?: boolean\n  /** `shadow` (default) records would-be decisions only; `enforce` acts on them. */\n  mode?: 'shadow' | 'enforce'\n  /** Which Jev entry point to call: typesafe (官方) / openrouter / custom. */\n  provider?: 'typesafe' | 'openrouter' | 'custom'\n  /** 自定义 endpoint URL（provider 为 custom 时必填）. */\n  endpoint?: string\n  /** 模型 ID（默认跟随 provider）. */\n  model?: string\n  /** 环境变量名（引用式 key，默认 TYPESAFE_API_KEY）. */\n  apiKeyEnv?: string\n  /** API key 值（/jev-key 写入；优先于环境变量）. */\n  apiKey?: string\n  /** Wall-clock budget per decision attempt in milliseconds (default 1500). */\n  timeoutMs?: number\n  /** Cooldown after consecutive failures in milliseconds (default 60000). */\n  cooldownMs?: number\n  /** Consecutive failures that open the cooldown (default 3). */\n  failureThreshold?: number\n  /** Maximum in-flight Jev requests (default 4; the provider rate-limits near 8). */\n  maxConcurrency?: number\n  /** Decision input cache capacity (default 512). */\n  cacheSize?: number\n  /** Directory for `telemetry.jsonl` (default `~/.dsh-jev-interceptor`). */\n  telemetryDir?: string\n  /** Trailing messages digested into the guard state (default 6). */\n  recentMessages?: number\n  /** Trailing messages digested into the pre-approval state (default 3). */\n  preapproveRecentMessages?: number\n  /** Per-message text bound in the state, characters (default 300). */\n  recentMessageChars?: number\n  /** Head characters kept from tool arguments in the state (default 2048). */\n  argsHeadChars?: number\n  /** Tail characters kept from tool arguments in the state (default 512). */\n  argsTailChars?: number\n\n  /** Guard hook master switch (default on when the plugin is enabled). */\n  guardEnabled?: boolean\n  /** Tool names skipped without a Jev call (read-only short-circuit, zero cost). */\n  guardReadOnlyTools?: string[]\n  /** Tool names never classified by this plugin. */\n  guardExcludeTools?: string[]\n  /** Minimum risk confidence to act on medium/low classifications (default 0.6). */\n  guardConfidenceMin?: number\n  /** Confidence for a high classification to deny instead of asking (default 0.85). */\n  guardDenyConfidence?: number\n  /** Irreversibility at/above which even a low-risk call escalates (default 0.2). */\n  guardIrreversibleCeiling?: number\n  /** Irreversibility required (with high risk + confidence) to deny instead of ask (default 0.5). */\n  guardIrreversibleDenyFloor?: number\n  /** Injection probability at/above which a call escalates regardless of risk (default 0.8). */\n  guardInjectionAskThreshold?: number\n\n  /** Pre-approval hook master switch (default on when the plugin is enabled). */\n  preapproveEnabled?: boolean\n  /** Tools eligible for auto-approval; empty (default) disables every auto-approval. */\n  preapproveToolAllowlist?: string[]\n  /** Confidence required on BOTH pre-approval questions (default 0.85). */\n  preapproveAutoApproveMin?: number\n  /** Irreversibility at/above which auto-approval is blocked (default 0.15). */\n  preapproveIrreversibleMax?: number\n  /** Injection suspicion at/above which auto-approval is blocked (default 0.5). */\n  preapproveInjectionSuspectMax?: number\n\n  /** Image-offload pre-planning master switch; default off (irreversible on disk). */\n  imageOffloadEnabled?: boolean\n  /** Token-pressure ratio [0,1] to trigger pre-planning (default 0.75). */\n  imageOffloadPressureThreshold?: number\n  /** Minimum unoffloaded candidate images to score (default 3). */\n  imageOffloadMinCandidates?: number\n  /** A message is sacrificial only when its score answer ≤ this (default 0.33). */\n  imageOffloadSacrificeScoreMax?: number\n  /** Sacrificial probability floor [0,1] (default 0.8). */\n  imageOffloadSacrificeProbMin?: number\n\n  /** 停滞检测（换参数死循环）总开关；默认关（照 imageOffloadEnabled 的 opt-in 先例）。 */\n  stagnationEnabled?: boolean\n  /** 每 (agent, 工具) 失败窗口容量（默认 8）。 */\n  stagnationWindow?: number\n  /** 窗口内失败次数达到该值才考虑发起 Jev 判断（默认 4）。 */\n  stagnationTriggerCount?: number\n  /** 窗口内失败占比下限 [0,1]（默认 0.75；成功即清空语义下是显式安全门）。 */\n  stagnationFailureRatioMin?: number\n  /** Jev 双 noul 判定「无进展」的行动置信门 [0,1]（默认 0.85）。 */\n  stagnationConfidenceMin?: number\n  /** 同一 (agent, 工具) 两次停滞提醒的最小间隔毫秒（默认 5 分钟）。 */\n  stagnationCooldownMs?: number\n  /** 进 Jev state 的参数预览长度（字符，默认 160）。 */\n  stagnationArgsPreviewChars?: number\n}\n\n/** Read-only dsh tool names (verified against the dsh tool registry) that never need classification. */\nconst DEFAULT_READ_ONLY_TOOLS = ['read', 'read_image', 'grep', 'glob', 'todo_write'] as const\n\n/**\n * Every default in one place: the schema references these for YAML loads, and\n * {@link resolveSettings} re-applies them for programmatic construction that\n * bypasses Schemastery normalization (the explicit resolve step dsh requires\n * over hidden `??` fallbacks scattered through `run()` paths).\n */\nexport const DEFAULTS = {\n  enabled: false,\n  mode: 'shadow' as const,\n  provider: 'typesafe' as const,\n  apiKeyEnv: 'TYPESAFE_API_KEY',\n  timeoutMs: 1500,\n  cooldownMs: 60_000,\n  failureThreshold: 3,\n  maxConcurrency: 4,\n  cacheSize: 512,\n  recentMessages: 6,\n  preapproveRecentMessages: 3,\n  recentMessageChars: 300,\n  argsHeadChars: 2048,\n  argsTailChars: 512,\n  guardEnabled: true,\n  guardReadOnlyTools: [...DEFAULT_READ_ONLY_TOOLS],\n  guardExcludeTools: [] as string[],\n  guardConfidenceMin: 0.6,\n  guardDenyConfidence: 0.85,\n  guardIrreversibleCeiling: 0.2,\n  guardIrreversibleDenyFloor: 0.5,\n  guardInjectionAskThreshold: 0.8,\n  preapproveEnabled: true,\n  preapproveToolAllowlist: [] as string[],\n  preapproveAutoApproveMin: 0.85,\n  preapproveIrreversibleMax: 0.15,\n  preapproveInjectionSuspectMax: 0.5,\n  stagnationEnabled: false,\n  stagnationWindow: 8,\n  stagnationTriggerCount: 4,\n  stagnationFailureRatioMin: 0.75,\n  stagnationConfidenceMin: 0.85,\n  stagnationCooldownMs: 300_000,\n  stagnationArgsPreviewChars: 160,\n} as const\n\nexport const Config: z<Config> = z.object({\n  enabled: z.boolean().default(DEFAULTS.enabled),\n  mode: z.union(['shadow', 'enforce']).default(DEFAULTS.mode),\n  provider: z.union(['typesafe', 'openrouter', 'custom']).default(DEFAULTS.provider),\n  endpoint: z.string(),\n  model: z.string(),\n  apiKeyEnv: z.string().role('credential-ref').default(DEFAULTS.apiKeyEnv),\n  apiKey: z.string().role('secret').description('API key 值（优先于环境变量）'),\n  timeoutMs: z.number().step(1).min(100).default(DEFAULTS.timeoutMs),\n  cooldownMs: z.number().step(1).min(1000).default(DEFAULTS.cooldownMs),\n  failureThreshold: z.number().step(1).min(1).default(DEFAULTS.failureThreshold),\n  maxConcurrency: z.number().step(1).min(1).max(8).default(DEFAULTS.maxConcurrency),\n  cacheSize: z.number().step(1).min(0).default(DEFAULTS.cacheSize),\n  telemetryDir: z.string(),\n  recentMessages: z.number().step(1).min(0).max(24).default(DEFAULTS.recentMessages),\n  preapproveRecentMessages: z.number().step(1).min(0).max(24).default(DEFAULTS.preapproveRecentMessages),\n  recentMessageChars: z.number().step(1).min(40).default(DEFAULTS.recentMessageChars),\n  argsHeadChars: z.number().step(1).min(64).default(DEFAULTS.argsHeadChars),\n  argsTailChars: z.number().step(1).min(0).default(DEFAULTS.argsTailChars),\n\n  guardEnabled: z.boolean().default(DEFAULTS.guardEnabled),\n  guardReadOnlyTools: z.array(z.string()).default([...DEFAULTS.guardReadOnlyTools]),\n  guardExcludeTools: z.array(z.string()).default(DEFAULTS.guardExcludeTools),\n  guardConfidenceMin: z.number().min(0).max(1).default(DEFAULTS.guardConfidenceMin),\n  guardDenyConfidence: z.number().min(0).max(1).default(DEFAULTS.guardDenyConfidence),\n  guardIrreversibleCeiling: z.number().min(0).max(1).default(DEFAULTS.guardIrreversibleCeiling),\n  guardIrreversibleDenyFloor: z.number().min(0).max(1).default(DEFAULTS.guardIrreversibleDenyFloor),\n  guardInjectionAskThreshold: z.number().min(0).max(1).default(DEFAULTS.guardInjectionAskThreshold),\n\n  preapproveEnabled: z.boolean().default(DEFAULTS.preapproveEnabled),\n  preapproveToolAllowlist: z.array(z.string()).default(DEFAULTS.preapproveToolAllowlist),\n  preapproveAutoApproveMin: z.number().min(0).max(1).default(DEFAULTS.preapproveAutoApproveMin),\n  preapproveIrreversibleMax: z.number().min(0).max(1).default(DEFAULTS.preapproveIrreversibleMax),\n  preapproveInjectionSuspectMax: z.number().min(0).max(1).default(DEFAULTS.preapproveInjectionSuspectMax),\n\n  imageOffloadEnabled: z.boolean().default(false),\n  imageOffloadPressureThreshold: z.number().min(0).max(1).default(0.75),\n  imageOffloadMinCandidates: z.number().step(1).min(1).default(3),\n  imageOffloadSacrificeScoreMax: z.number().min(0).max(1).default(0.33),\n  imageOffloadSacrificeProbMin: z.number().min(0).max(1).default(0.8),\n\n  stagnationEnabled: z.boolean().default(DEFAULTS.stagnationEnabled),\n  stagnationWindow: z.number().step(1).min(2).max(32).default(DEFAULTS.stagnationWindow),\n  stagnationTriggerCount: z.number().step(1).min(2).max(16).default(DEFAULTS.stagnationTriggerCount),\n  stagnationFailureRatioMin: z.number().min(0.5).max(1).default(DEFAULTS.stagnationFailureRatioMin),\n  stagnationConfidenceMin: z.number().min(0.5).max(1).default(DEFAULTS.stagnationConfidenceMin),\n  stagnationCooldownMs: z.number().step(1).min(30_000).default(DEFAULTS.stagnationCooldownMs),\n  stagnationArgsPreviewChars: z.number().step(1).min(16).max(1024).default(DEFAULTS.stagnationArgsPreviewChars),\n})\n\n/** Fully-defaulted settings, the one resolved shape the rest of the plugin consumes. */\nexport interface ResolvedSettings {\n  readonly mode: 'shadow' | 'enforce'\n  readonly timeoutMs: number\n  readonly cooldownMs: number\n  readonly failureThreshold: number\n  readonly maxConcurrency: number\n  readonly cacheSize: number\n  readonly telemetryDir: string\n  readonly recentMessages: number\n  readonly preapproveRecentMessages: number\n  readonly recentMessageChars: number\n  readonly argsHeadChars: number\n  readonly argsTailChars: number\n  readonly guardEnabled: boolean\n  readonly readOnlyTools: ReadonlySet<string>\n  readonly excludeTools: ReadonlySet<string>\n  readonly guardConfidenceMin: number\n  readonly guardDenyConfidence: number\n  readonly guardIrreversibleCeiling: number\n  readonly guardIrreversibleDenyFloor: number\n  readonly guardInjectionAskThreshold: number\n  readonly preapproveEnabled: boolean\n  readonly preapproveToolAllowlist: ReadonlySet<string>\n  readonly preapproveAutoApproveMin: number\n  readonly preapproveIrreversibleMax: number\n  readonly preapproveInjectionSuspectMax: number\n  readonly stagnationEnabled: boolean\n  readonly stagnationWindow: number\n  readonly stagnationTriggerCount: number\n  readonly stagnationFailureRatioMin: number\n  readonly stagnationConfidenceMin: number\n  readonly stagnationCooldownMs: number\n  readonly stagnationArgsPreviewChars: number\n  readonly apiKeyEnv: string\n}\n\n/**\n * The explicit resolve step from raw config to fully-defaulted settings.\n * @param config - raw plugin config (YAML-validated or programmatic).\n * @returns settings with every field populated.\n */\nexport function resolveSettings(config: Config): ResolvedSettings {\n  return {\n    mode: config.mode ?? DEFAULTS.mode,\n    timeoutMs: config.timeoutMs ?? DEFAULTS.timeoutMs,\n    cooldownMs: config.cooldownMs ?? DEFAULTS.cooldownMs,\n    failureThreshold: config.failureThreshold ?? DEFAULTS.failureThreshold,\n    maxConcurrency: config.maxConcurrency ?? DEFAULTS.maxConcurrency,\n    cacheSize: config.cacheSize ?? DEFAULTS.cacheSize,\n    // Follows the dsh home ($DSH_HOME, default ~/.dsh) so telemetry lives\n    // with the rest of the harness data under a relocated home.\n    telemetryDir: config.telemetryDir && config.telemetryDir.length > 0\n      ? config.telemetryDir\n      : dshHomePath('plugins', 'dsh-jev-interceptor'),\n    recentMessages: config.recentMessages ?? DEFAULTS.recentMessages,\n    preapproveRecentMessages: config.preapproveRecentMessages ?? DEFAULTS.preapproveRecentMessages,\n    recentMessageChars: config.recentMessageChars ?? DEFAULTS.recentMessageChars,\n    argsHeadChars: config.argsHeadChars ?? DEFAULTS.argsHeadChars,\n    argsTailChars: config.argsTailChars ?? DEFAULTS.argsTailChars,\n    guardEnabled: config.guardEnabled ?? DEFAULTS.guardEnabled,\n    readOnlyTools: new Set(config.guardReadOnlyTools ?? DEFAULTS.guardReadOnlyTools),\n    excludeTools: new Set(config.guardExcludeTools ?? DEFAULTS.guardExcludeTools),\n    guardConfidenceMin: config.guardConfidenceMin ?? DEFAULTS.guardConfidenceMin,\n    guardDenyConfidence: config.guardDenyConfidence ?? DEFAULTS.guardDenyConfidence,\n    guardIrreversibleCeiling: config.guardIrreversibleCeiling ?? DEFAULTS.guardIrreversibleCeiling,\n    guardIrreversibleDenyFloor: config.guardIrreversibleDenyFloor ?? DEFAULTS.guardIrreversibleDenyFloor,\n    guardInjectionAskThreshold: config.guardInjectionAskThreshold ?? DEFAULTS.guardInjectionAskThreshold,\n    preapproveEnabled: config.preapproveEnabled ?? DEFAULTS.preapproveEnabled,\n    preapproveToolAllowlist: new Set(config.preapproveToolAllowlist ?? DEFAULTS.preapproveToolAllowlist),\n    preapproveAutoApproveMin: config.preapproveAutoApproveMin ?? DEFAULTS.preapproveAutoApproveMin,\n    preapproveIrreversibleMax: config.preapproveIrreversibleMax ?? DEFAULTS.preapproveIrreversibleMax,\n    preapproveInjectionSuspectMax: config.preapproveInjectionSuspectMax ?? DEFAULTS.preapproveInjectionSuspectMax,\n    stagnationEnabled: config.stagnationEnabled ?? DEFAULTS.stagnationEnabled,\n    stagnationWindow: config.stagnationWindow ?? DEFAULTS.stagnationWindow,\n    stagnationTriggerCount: config.stagnationTriggerCount ?? DEFAULTS.stagnationTriggerCount,\n    stagnationFailureRatioMin: config.stagnationFailureRatioMin ?? DEFAULTS.stagnationFailureRatioMin,\n    stagnationConfidenceMin: config.stagnationConfidenceMin ?? DEFAULTS.stagnationConfidenceMin,\n    stagnationCooldownMs: config.stagnationCooldownMs ?? DEFAULTS.stagnationCooldownMs,\n    stagnationArgsPreviewChars: config.stagnationArgsPreviewChars ?? DEFAULTS.stagnationArgsPreviewChars,\n    apiKeyEnv: config.apiKeyEnv ?? DEFAULTS.apiKeyEnv,\n  }\n}\n\n/** TypeSafe's public decisions endpoint. */\nexport const TYPESAFE_ENDPOINT = 'https://api.typesafe.ai/v1/systemone'\n\n/** OpenRouter's alpha decisions endpoint (model ids carry a `~` prefix there). */\nexport const OPENROUTER_ENDPOINT = 'https://openrouter.ai/api/alpha/decisions'\n\n/** Default model id for the TypeSafe provider preset. */\nexport const TYPESAFE_MODEL = 'jev-latest'\n\n/** Default model id for the OpenRouter provider preset. */\nexport const OPENROUTER_MODEL = '~typesafe/jev-latest'\n\n/**\n * Resolve the effective endpoint and model for the configured provider.\n * @param config - validated plugin configuration.\n * @returns the endpoint URL and model id.\n * @throws when `custom` is selected without an explicit endpoint and model.\n */\nexport function resolveEndpoint(config: Config): { endpoint: string; model: string } {\n  if (config.provider === 'custom') {\n    if (config.endpoint === undefined || config.endpoint.length === 0) {\n      throw new Error('dsh-jev-interceptor: provider \"custom\" requires endpoint')\n    }\n    if (config.model === undefined || config.model.length === 0) {\n      throw new Error('dsh-jev-interceptor: provider \"custom\" requires model')\n    }\n    return { endpoint: config.endpoint, model: config.model }\n  }\n  const preset = config.provider === 'openrouter'\n    ? { endpoint: OPENROUTER_ENDPOINT, model: OPENROUTER_MODEL }\n    : { endpoint: TYPESAFE_ENDPOINT, model: TYPESAFE_MODEL }\n  return {\n    endpoint: config.endpoint ?? preset.endpoint,\n    model: config.model ?? preset.model,\n  }\n}\n\n/** Profile entry id of the jev-interceptor row: the settings-forms update target. */\nexport const SETTINGS_NS = 'jev-interceptor'\n\n/** The runtime-tunable subset of the row config. */\nexport interface LiveSettings {\n  /** Master switch; `false` leaves stock behavior untouched. */\n  enabled: boolean\n  /** `shadow` records would-be decisions only; `enforce` acts on them. */\n  mode: 'shadow' | 'enforce'\n}\n\n/**\n * Extract the live subset from a raw section value (row config or resolved\n * settings snapshot); anything malformed falls back to inert defaults.\n * @param value - raw value from config or the settings service.\n * @returns the safe live settings.\n */\nexport function liveOf(value: { enabled?: boolean; mode?: 'shadow' | 'enforce' } | undefined | null): LiveSettings {\n  return {\n    enabled: value?.enabled === true,\n    mode: value?.mode === 'shadow' || value?.mode === 'enforce' ? value.mode : 'shadow',\n  }\n}\n"
